sen wir zuerst ein kleines Programm erstellen. "},{"text":"Kopiere den folgenden Code in eine neue Datei und speichere unter dem Namen ","color":1},{"text":"bluefruitconnect_controlpad.py","strong":true,"color":1},{"text":" auf deinem Board.","color":1}]}],"id":"1b8658b9-d2a4-42ea-9036-7cbc1c376b0c"},{"plugin":"highlight","state":{"code":"from adafruit_ble import BLERadio
from adafruit_ble.advertising.standard import ProvideServicesAdvertisement
from adafruit_ble.services.nordic import UARTService
from adafruit_bluefruit_connect.packet import Packet

# Only the packet classes that are imported will be known to Packet.
from adafruit_bluefruit_connect.button_packet import ButtonPacket

ble = BLERadio()
uart_server = UARTService()
advertisement = ProvideServicesAdvertisement(uart_server)

while True:
    print("WAITING...")
    # Advertise when not connected.
    ble.start_advertising(advertisement)
    while not ble.connected:
        pass

    # Connected
    ble.stop_advertising()
    print("CONNECTED")

    # Loop and read packets
    while ble.connected:

        # Keeping trying until a good packet is received
        try:
            packet = Packet.from_stream(uart_server)
        except ValueError:
            continue

        # Only handle button packets
        if isinstance(packet, ButtonPacket) and packet.pressed:
            if packet.button == ButtonPacket.UP:
                print("Button UP")
            if packet.button == ButtonPacket.DOWN:
                print("Button DOWN")
            if packet.button == ButtonPacket.LEFT:
                print("Button LEFT")
            if packet.button == ButtonPacket.RIGHT:
                print("Button RIGHT")
            if packet.button == ButtonPacket.BUTTON_1:
                print("Button 1")
            if packet.button == ButtonPacket.BUTTON_2:
                print("Button 2")
            if packet.button == ButtonPacket.BUTTON_3:
                print("Button 3")
            if packet.button == ButtonPacket.BUTTON_4:
                print("Button 4")

    # Disconnected
    print("DISCONNECTED")","language":"python","showLineNumbers":true},"id":"2b8f0478-7704-49af-952a-c31dace19c60"},{"plugin":"text","state":[{"type":"h","level":2,"children":[{"text":"Die App"}]}],"id":"e5d79a21-4093-4863-8998-a1f9567efa7a"},{"plugin":"multimedia","state":{"explanation":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"Aktiviere Bluetooth auf deinem Smartphone und starte die App."}]}],"id":"9a07aa9b-55eb-4d02-83f5-229b3726f3d2"},{"plugin":"text","state":[{"type":"p","children":[{"text":"Wähle unter Filter die Checkbox "},{"text":"Must have UART Service","strong":true}]}],"id":"a53f339f-8f4d-4a34-8efe-34ec06af9a23"},{"plugin":"text","state":[{"type":"p","children":[{"text":"Tippe jetzt auf den CONNECT Button neben dem Namen deines Boards"}]}],"id":"4deff4d8-9281-4375-9b83-185e3578779c"}],"id":"c8b8c27e-05d2-4cdf-a5f0-d900d6220f54"},"multimedia":{"plugin":"image","state":{"src":"https://assets.serlo.org/61a3b392d87ef_914af23ea59f40c6f098933a1dea437a48b47ecf.jpg","caption":{"plugin":"text","state":[{"type":"p","children":[{}]}],"id":"20bf26d0-fb79-4e69-b74f-75a66ca62aa2"}},"id":"0eceaf7c-47c6-47c9-9364-9ff07552bb3e"},"illustrating":true,"width":50},"id":"e95d7f22-5823-46ac-87ce-65b26cd31c8a"},{"plugin":"multimedia","state":{"explanation":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"Wähle das Modul "},{"text":"Controller","strong":true},{"text":" aus."}]}],"id":"451727b3-ee81-433c-acbc-e351a6a66aaa"}],"id":"d218db2f-fbb6-457f-86d3-9661905ed377"},"multimedia":{"plugin":"image","state":{"src":"https://assets.serlo.org/61a3b3a1945a2_db45d31698e6193e48f2f02dbf30f1387877a2a4.jpg","caption":{"plugin":"text","state":[{"type":"p","children":[{}]}],"id":"0ab2b562-3dde-4141-9ff5-970c742e1ad8"}},"id":"04a2f5b5-e261-4912-8356-536a35c882ed"},"illustrating":true,"width":50},"id":"8c0408ab-40d4-43ed-a0ae-37ff3c935a69"},{"plugin":"multimedia","state":{"explanation":{"plugin":"rows","state":[{"p